package com.apixenglish.center.modules.learningreport.controller;import com.apixenglish.center.common.response.ApiResponse;import com.apixenglish.center.modules.learningreport.dto.LearningReportDtos.*;import com.apixenglish.center.modules.learningreport.service.LearningReportService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/learning-reports") @RequiredArgsConstructor public class LearningReportController{private final LearningReportService service;
 @GetMapping @PreAuthorize("hasAuthority('learning_report:read')")public ApiResponse<Page<Response>>list(@RequestParam(required=false)UUID classId,@RequestParam(required=false)UUID studentId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(service.list(classId,studentId,PageRequest.of(page,size)));}
 @GetMapping("/{id}")@PreAuthorize("hasAuthority('learning_report:read')")public ApiResponse<Response>get(@PathVariable UUID id){return ApiResponse.success(service.get(id));}@PostMapping @PreAuthorize("hasAuthority('learning_report:create')")public ApiResponse<Response>create(@Valid @RequestBody Upsert r){return ApiResponse.success(service.create(r));}@PutMapping("/{id}")@PreAuthorize("hasAuthority('learning_report:update')")public ApiResponse<Response>update(@PathVariable UUID id,@Valid @RequestBody Upsert r){return ApiResponse.success(service.update(id,r));}
 @PostMapping("/{id}/submit")@PreAuthorize("hasAuthority('learning_report:submit')")public ApiResponse<Response>submit(@PathVariable UUID id){return ApiResponse.success(service.submit(id));}@PostMapping("/{id}/approve")@PreAuthorize("hasAuthority('learning_report:approve')")public ApiResponse<Response>approve(@PathVariable UUID id){return ApiResponse.success(service.approve(id));}@PostMapping("/{id}/reject")@PreAuthorize("hasAuthority('learning_report:reject')")public ApiResponse<Response>reject(@PathVariable UUID id,@Valid @RequestBody Reject r){return ApiResponse.success(service.reject(id,r.reason()));}@PostMapping({"/{id}/deliver","/{id}/publish"})@PreAuthorize("hasAuthority('learning_report:deliver')")public ApiResponse<Response>deliver(@PathVariable UUID id){return ApiResponse.success(service.deliver(id));}}
